private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b0 = bb.get(i) & 0xFF;
    int codePoint;
    int bytes;
    if ((b0 & 0x80) == 0) {
        // 1-byte sequence
        codePoint = b0;
        bytes = 1;
    } else if ((b0 & 0xE0) == 0xC0) {
        // 2-byte sequence
        int b1 = bb.get(i + 1) & 0xFF;
        codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        bytes = 2;
    } else if ((b0 & 0xF0) == 0xE0) {
        // 3-byte sequence
        int b1 = bb.get(i + 1) & 0xFF;
        int b2 = bb.get(i + 2) & 0xFF;
        codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        bytes = 3;
    } else if ((b0 & 0xF8) == 0xF0) {
        // 4-byte sequence
        int b1 = bb.get(i + 1) & 0xFF;
        int b2 = bb.get(i + 2) & 0xFF;
        int b3 = bb.get(i + 3) & 0xFF;
        codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        bytes = 4;
    } else {
        // Invalid leading byte, use replacement character
        codePoint = 0xFFFD;
        bytes = 1;
    }

    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        // Encode surrogate pair
        codePoint -= 0x10000;
        char high = (char) ((codePoint >> 10) + 0xD800);
        char low = (char) ((codePoint & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
    }

    return i + bytes;
}

