public String format(LoggingEvent event){
    StringBuilder sb = new StringBuilder();
    String pat = this.pattern; // conversion pattern stored in the class
    for (int i = 0; i < pat.length(); i++) {
        char c = pat.charAt(i);
        if (c == '%' && i + 1 < pat.length()) {
            char next = pat.charAt(i + 1);
            switch (next) {
                case 'd':
                    // date/time
                    sb.append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                            .format(new java.util.Date(event.getTimeStamp())));
                    i++;
                    break;
                case 'p':
                    // priority/level
                    sb.append(event.getLevel());
                    i++;
                    break;
                case 'c':
                    // logger name
                    sb.append(event.getLoggerName());
                    i++;
                    break;
                case 'm':
                    // message
                    Object msg = event.getMessage();
                    sb.append(msg != null ? msg.toString() : "null");
                    i++;
                    break;
                case 'n':
                    // newline
                    sb.append(System.lineSeparator());
                    i++;
                    break;
                default:
                    sb.append(c);
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

