    // If the header is present and can be parsed as a long, return its value.
    // Otherwise, return -1 to indicate that the content length is unknown.
    String lengthHeader = request.getHeader("Content-Length");
    if (lengthHeader != null) {
        try {
            return Long.parseLong(lengthHeader);
