static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    int year  = (int)(timeBucket / 10000);
    int month = (int)((timeBucket % 10000) / 100);
    int day   = (int)(timeBucket % 100);
    int newDay = 1 + ((day - 1) / dayStep) * dayStep;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i++; // skip low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

