public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Pattern to find ${var} placeholders
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    // Limit the number of substitution passes to avoid infinite loops
    int maxPasses = 10;
    for (int pass = 0; pass < maxPasses; pass++) {
        java.util.regex.Matcher matcher = pattern.matcher(value);
        if (!matcher.find()) {
            break; // No more placeholders
        }
        StringBuffer sb = new StringBuffer();
        matcher.reset();
        while (matcher.find()) {
            String subKey = matcher.group(1);
            String subVal = props.getProperty(subKey);
            if (subVal == null) {
                subVal = "";
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(subVal));
        }
        matcher.appendTail(sb);
        value = sb.toString();
    }
    return value;
}

