private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    int start = strLen - suffixLen;
    return str.regionMatches(ignoreCase, start, suffix, 0, suffixLen);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split the path into segments
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        // Separate matrix parameters (if any)
        String[] segParts = part.split(";", 2);
        String segPath = segParts[0];
        if (decode) {
            try {
                segPath = java.net.URLDecoder.decode(segPath, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        // Matrix parameters are ignored in this implementation
        segments.add(new PathSegmentImpl(segPath, null));
    }
    return segments;
}

