private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    // Method descriptor: starts with '('
    if (descriptor.charAt(0) == '(') {
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        int i = 1; // skip '('
        while (i < end) {
            char c = descriptor.charAt(i);
            // Skip array brackets
            while (i < end && descriptor.charAt(i) == '[') {
                i++;
            }
            // Skip base type
            if (i < end) {
                char base = descriptor.charAt(i);
                if (base == 'L') {
                    // Object type: skip until ';'
                    i++; // skip 'L'
                    while (i < end && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i < end) {
                        i++; // skip ';'
                    }
                } else {
                    // Primitive type: single char
                    i++;
                }
            }
            // Pop one type from the stack
            outputStack.pop();
        }
    } else {
        // Single type descriptor
        int i = 0;
        char c = descriptor.charAt(i);
        if (c == 'V') {
            // Void type: nothing to pop
            return;
        }
        // Skip array brackets
        while (i < descriptor.length() && descriptor.charAt(i) == '[') {
            i++;
        }
        // Skip base type
        if (i < descriptor.length()) {
            char base = descriptor.charAt(i);
            if (base == 'L') {
                // Object type: skip until ';'
                i++; // skip 'L'
                while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i < descriptor.length()) {
                    i++; // skip ';'
                }
            } else {
                // Primitive type: single char
                i++;
            }
        }
        // Pop one type from the stack
        outputStack.pop();
    }
}

@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b is null");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException("off=" + off + ", len=" + len + ", b.length=" + b.length);
    }
    if (len == 0) {
        return;
    }
    // Ensure capacity
    if (count + len > buf.length) {
        int newCapacity = Math.max(buf.length << 1, count + len);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count += len;
}

public static final <V> void swap(V[] arr, int i, int j) {
