@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }

    if (value == null) {
        return null;
    }

    // If the value is already a Character, return it directly
    if (value instanceof Character) {
        return value;
    }

    // Convert from String: must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String to Character: length != 1");
        }
    }

    // Convert from Number: cast the numeric value to a char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }

    // Unsupported conversion
    throw new IllegalArgumentException(
        "Cannot convert value of type " + value.getClass().getName() + " to Character");
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
    }
    String lowerStr = str.toLowerCase();
    Set<Character> searchChars = new HashSet<>();
    for (String s : searchStrArray) {
        if (s == null) {
            continue;
        }
        for (int i = 0; i < s.length(); i++) {
            searchChars.add(Character.toLowerCase(s.charAt(i)));
        }
    }
    for (int i = 0; i < lowerStr.length(); i++) {
        if (searchChars.contains(lowerStr.charAt(i))) {
            return true;
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        boolean isPrime = true;
        if (candidate < 2) {
            isPrime = false;
        } else if (candidate == 2 || candidate == 3) {
            isPrime = true;
        } else if (candidate % 2 == 0 || candidate % 3 == 0) {
            isPrime = false;
        } else {
            int i = 5;
            int w = 2;
            while (i * i <= candidate) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
                i += w;
                w = 6 - w;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2;
    }
}

