    int descriptorIndex = addConstantUtf8(descriptor);

    // Search for an existing CONSTANT_NameAndType_info with the same name and descriptor indices
    for (int i = 1; i < constantPool.size(); i++) {
        ConstantPoolInfo entry = constantPool.get(i);
        if (entry instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo nt = (ConstantNameAndTypeInfo) entry;
            if (nt.nameIndex == nameIndex && nt.descriptorIndex == descriptorIndex) {
                return i; // Found an existing entry, return its index
            }
        }
    }

    // No existing entry found; create a new one
    ConstantNameAndTypeInfo newEntry = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
    int newIndex = constantPool.size(); // Index where the new entry will be placed
    constantPool.add(newEntry);
    return newIndex;
}

