public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> ranges = new ArrayList<>();
    // Collect all segments from current profiles
    List<Segment> allSegments = new ArrayList<>();
    for (Profile profile : profiles) {
        allSegments.addAll(profile.getSegments());
    }
    // Sort segments by start position
    allSegments.sort(Comparator.comparingInt(Segment::getStart));
    // Merge overlapping or adjacent segments into sequence ranges
    int currentStart = -1;
    int currentEnd = -1;
    for (Segment seg : allSegments) {
        if (currentStart == -1) {
            currentStart = seg.getStart();
            currentEnd = seg.getEnd();
        } else {
            if (seg.getStart() <= currentEnd + 1) {
                currentEnd = Math.max(currentEnd, seg.getEnd());
            } else {
                ranges.add(new SequenceRange(currentStart, currentEnd));
                currentStart = seg.getStart();
                currentEnd = seg.getEnd();
            }
        }
    }
    if (currentStart != -1) {
        ranges.add(new SequenceRange(currentStart, currentEnd));
    }
    return ranges;
}

