public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }
    // Ensure indices are within bounds
    int n = arr.length;
    if (from < 0) {
        from = 0;
    }
    if (to >= n) {
        to = n - 1;
    }
    // Swap elements until the middle of the range is reached
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

