private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparators = new ArrayList<>();
    for (E e : graph.getEdges()){
        Collection<Integer> neighborhood = graph.getNeighbors(e);
        List<Pair<Integer,Integer>> separators = new ArrayList<>();
        Integer[] verts = neighborhood.toArray(new Integer[0]);
        for (int i = 0; i < verts.length; i++){
            for (int j = i + 1; j < verts.length; j++){
                separators.add(new Pair<>(verts[i], verts[j]));
            }
        }
        globalSeparators.add(new Pair<>(separators, e));
    }
    return globalSeparators;
}

