public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    if (row < 0 || row >= table.getRowCount()) {
        return;
    }
    // Ensure selection and scrolling happen on the EDT
    SwingUtilities.invokeLater(() -> {
        table.setRowSelectionInterval(row, row);
        Rectangle rect = table.getCellRect(row, 0, true);
        if (rect != null) {
            table.scrollRectToVisible(rect);
        }
    });
    // Delay repaint until after the selection and scrolling have been processed
    SwingUtilities.invokeLater(() -> {
        table.repaint();
    });
}

public ByteVector putInt(final int intValue){
    int newSize = size + 4;
    if (newSize > buf.length) {
        int newCapacity = Math.max(buf.length * 2, newSize);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, size);
        buf = newBuf;
    }
    buf[size]     = (byte) (intValue >>> 24);
    buf[size + 1] = (byte) (intValue >>> 16);
    buf[size + 2] = (byte) (intValue >>> 8);
    buf[size + 3] = (byte) intValue;
    size = newSize;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    if (a == b) {
        return true;
    }
    if (a == null || b == null) {
        return false;
    }
    if (count < 0) {
        throw new IllegalArgumentException("count must be non-negative");
    }
    if (count > a.length || count > b.length) {
        throw new ArrayIndexOutOfBoundsException("count exceeds array length");
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (name == null || nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    boolean inWord = false;
    for (int i = nameStart; i < name.length(); i++) {
        char c = name.charAt(i);
        if (c == '.' || c == '_' || c == ' ') {
            inWord = false;
            continue;
        }
        if (!inWord) {
            buf.append(Character.toUpperCase(c));
            inWord = true;
        }
    }
}

