private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.size() <= 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = list.get(j);
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        Integer maxLower = Integer.MIN_VALUE;
        for (int j = 0; j < keys.size(); j++) {
            if (i == j) continue;
            K other = keys.get(j);
            if (other instanceof Comparable) {
                @SuppressWarnings("unchecked")
                Comparable<K> comp = (Comparable<K>) other;
                if (comp.compareTo(key) < 0) {
                    Integer val = (Integer) other;
                    if (val > maxLower) {
                        maxLower = val;
                    }
                }
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

