private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int bound = keys.size(); // default if no greater key
        Comparable<K> compKey = (Comparable<K>) key;
        for (int j = i + 1; j < keys.size(); j++) {
            K candidate = keys.get(j);
            if (compKey.compareTo(candidate) < 0) {
                bound = j;
                break;
            }
        }
        upperBounds.add(bound);
    }
    return upperBounds;
}

